import { ERROR_CODES, LedgerError } from './errors.mjs';

function invalidTiers(msg) {
  return new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, msg);
}

/**
 * Validates tiers and returns a sorted copy (ascending by upTo, unbounded last).
 * Does not mutate the input.
 */
function normalizeTiers(tiers) {
  if (!Array.isArray(tiers) || tiers.length === 0) {
    throw invalidTiers('tiers must be a non-empty array');
  }
  const seen = new Set();
  let unbounded = 0;
  const copy = tiers.map((tier, originalIndex) => {
    if (tier === null || typeof tier !== 'object') {
      throw invalidTiers('each tier must be an object');
    }
    const { upTo, unitRateCents } = tier;
    if (typeof unitRateCents !== 'number' || !Number.isFinite(unitRateCents) || unitRateCents < 0) {
      throw invalidTiers('unitRateCents must be a finite number >= 0');
    }
    let cap;
    if (upTo === null || upTo === Infinity) {
      unbounded += 1;
      if (unbounded > 1) throw invalidTiers('at most one unbounded tier is allowed');
      cap = Infinity;
    } else {
      if (typeof upTo !== 'number' || !Number.isInteger(upTo) || upTo <= 0) {
        throw invalidTiers('upTo must be null, Infinity, or a positive integer');
      }
      if (seen.has(upTo)) throw invalidTiers('duplicate upTo');
      seen.add(upTo);
      cap = upTo;
    }
    return { cap, unitRateCents, originalIndex };
  });
  copy.sort((a, b) => (a.cap === b.cap ? 0 : a.cap < b.cap ? -1 : 1));
  return copy;
}

/**
 * Computes graduated (marginal/tiered) usage charges.
 * `tierIndex` in the breakdown is the index within the sorted tier list.
 *
 * @param {number} units
 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
 * @returns {{ totalCents: number, breakdown: Array<{ tierIndex: number, upTo: number | null, units: number, unitRateCents: number, subtotalCents: number }> }}
 */
export function computeGraduatedCharge(units, tiers) {
  const sorted = normalizeTiers(tiers);
  if (typeof units !== 'number' || !Number.isFinite(units) || units < 0) {
    throw new LedgerError(ERROR_CODES.ERR_NEGATIVE_UNITS, 'units must be >= 0');
  }
  if (units === 0) {
    return { totalCents: 0, breakdown: [] };
  }

  let prevUpTo = 0;
  let totalCents = 0;
  const breakdown = [];

  for (let i = 0; i < sorted.length; i += 1) {
    const { cap, unitRateCents } = sorted[i];
    const bandUnits = Math.min(units, cap) - prevUpTo;
    if (bandUnits > 0) {
      const subtotalCents = Math.round(bandUnits * unitRateCents);
      totalCents += subtotalCents;
      breakdown.push({
        tierIndex: i,
        upTo: cap === Infinity ? null : cap,
        units: bandUnits,
        unitRateCents,
        subtotalCents
      });
    }
    if (units <= cap) break;
    prevUpTo = cap;
  }

  return { totalCents, breakdown };
}
